//! Hold invoices over NWC, on a single chain.
//!
//! Mission 02.2. A hold invoice is issued against a payment hash chosen by
//! the caller rather than generated by the payee, and is not settled by
//! payment — the payee must settle it explicitly, or cancel it. That is the
//! primitive a cross-chain swap needs, because it lets two legs on two
//! chains share one hash.
//!
//! This scenario exercises both outcomes on one chain, and establishes how
//! a *held* payment behaves over NWC: the request cannot complete until the
//! payee acts, so the response is outstanding across a relay for the whole
//! hold period. The answer decides how mission 02.4 is written.
//!
//! Alice issues; Bob pays.

use std::path::PathBuf;
use std::time::{Duration, Instant};

use anyhow::{Context, Result};
use nostr_sdk::prelude::*;
use sha2::{Digest, Sha256};
use tracing::info;

use dln_e2e_test::bitcoind::BitcoindHarness;
use dln_e2e_test::dln_node_client::{DlnNode, SignerMode};
use dln_e2e_test::{relay, util};

const CHANNEL_SATS: u64 = 2_000_000;
const PUSH_MSAT: u64 = 500_000;
const AMOUNT_MSAT: u64 = 100_000;

#[tokio::main]
async fn main() {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new("info")),
        )
        .init();

    match run_scenario().await {
        Ok(()) => {
            println!("\n=== PASS ===");
            std::process::exit(0);
        }
        Err(e) => {
            eprintln!("\n=== FAIL ===\n{e:?}");
            std::process::exit(1);
        }
    }
}

/// A fresh preimage and its hash, hex encoded.
fn new_secret() -> (String, String) {
    let preimage = Keys::generate().secret_key().to_secret_bytes();
    let hash = Sha256::digest(preimage);
    (hex::encode(preimage), hex::encode(hash))
}

async fn run_scenario() -> Result<()> {
    let output_dir = PathBuf::from(
        std::env::var("OUTPUT_DIR").unwrap_or_else(|_| util::unique_tmp_dir("hold-invoice")),
    );
    let _ = std::fs::remove_dir_all(&output_dir);
    std::fs::create_dir_all(&output_dir)?;
    info!("Output directory: {}", output_dir.display());

    info!("Step 1: Starting bitcoind (Core, regtest)");
    let bitcoind = BitcoindHarness::start().await;
    let miner_address = bitcoind.get_new_address().await;
    bitcoind.mine_blocks(110, &miner_address).await;

    // Bind the handle: dropping it stops the container (see mission 02.1).
    let (_relay_container, relay_url) = relay::start_relay().await;

    info!("Step 2: Starting alice and bob (plain, no VLS)");
    let alice = DlnNode::start_named(
        "alice", SignerMode::Plain, &bitcoind, &miner_address, &relay_url, &output_dir,
    )
    .await
    .context("failed to start alice")?;
    let bob = DlnNode::start_named(
        "bob", SignerMode::Plain, &bitcoind, &miner_address, &relay_url, &output_dir,
    )
    .await
    .context("failed to start bob")?;
    anyhow::ensure!(
        alice.node_id() != bob.node_id(),
        "alice and bob report the same node_id"
    );

    // Bob pays, so bob funds the channel.
    info!("Step 3: bob -> alice channel, {CHANNEL_SATS} sats");
    let alice_id = alice.node_id();
    let alice_addr = format!("127.0.0.1:{}", alice.ln_port);
    bob.open_channel(&alice_id, &alice_addr, CHANNEL_SATS, Some(PUSH_MSAT))
        .await
        .context("open_channel failed")?;
    wait_for(Duration::from_secs(120), "channel ready", || async {
        bitcoind.mine_blocks(1, &miner_address).await;
        Ok(bob.has_ready_channel_with(&alice_id).await
            && alice.has_ready_channel_with(&bob.node_id()).await)
    })
    .await?;

    // ── Settle path ─────────────────────────────────────────────────────
    info!("Step 4: settle path");
    let (preimage, payment_hash) = new_secret();
    let alice_before = alice.get_balance_msat().await?;

    let invoice = alice
        .make_hold_invoice(AMOUNT_MSAT, &payment_hash, "hold: settle")
        .await
        .context("alice make_hold_invoice failed")?;
    info!("  alice issued a hold invoice for {payment_hash}");

    // Bob's payment and alice's settle must overlap: the payment cannot
    // complete until she settles, and she should not settle until it is
    // actually held.
    let started = Instant::now();
    let pay = bob.pay_invoice(&invoice);
    let settle = async {
        wait_for(Duration::from_secs(60), "invoice to be held", || async {
            Ok(alice.lookup_invoice(&payment_hash).await.is_ok())
        })
        .await?;
        tokio::time::sleep(Duration::from_secs(3)).await;
        info!("  alice settling with the preimage");
        alice.settle_hold_invoice(&preimage).await
    };
    let (pay_result, settle_result) = tokio::join!(pay, settle);
    settle_result.context("alice settle_hold_invoice failed")?;
    let observed = pay_result.context("bob pay_invoice failed")?;
    let held_for = started.elapsed();

    // The point of the exercise: the payer ends up holding a secret it
    // never chose.
    anyhow::ensure!(
        observed == preimage,
        "bob's pay_invoice returned {observed}, expected {preimage}"
    );
    info!(
        "  bob's payment returned the preimage after {:.1}s held",
        held_for.as_secs_f32()
    );

    wait_for(Duration::from_secs(30), "alice's balance to rise", || async {
        Ok(alice.get_balance_msat().await? >= alice_before + AMOUNT_MSAT)
    })
    .await
    .context("alice was not credited after settling")?;

    // ── Cancel path ─────────────────────────────────────────────────────
    info!("Step 5: cancel path");
    let (_unused_preimage, cancel_hash) = new_secret();
    let alice_mid = alice.get_balance_msat().await?;

    let invoice2 = alice
        .make_hold_invoice(AMOUNT_MSAT, &cancel_hash, "hold: cancel")
        .await
        .context("alice make_hold_invoice (cancel) failed")?;

    let pay2 = bob.pay_invoice(&invoice2);
    let cancel = async {
        wait_for(Duration::from_secs(60), "invoice to be held", || async {
            Ok(alice.lookup_invoice(&cancel_hash).await.is_ok())
        })
        .await?;
        tokio::time::sleep(Duration::from_secs(3)).await;
        info!("  alice cancelling");
        alice.cancel_hold_invoice(&cancel_hash).await
    };
    let (pay2_result, cancel_result) = tokio::join!(pay2, cancel);
    cancel_result.context("alice cancel_hold_invoice failed")?;
    anyhow::ensure!(
        pay2_result.is_err(),
        "bob's payment succeeded against a cancelled hold invoice"
    );
    info!("  bob's payment failed as expected: {}", pay2_result.unwrap_err());

    let alice_after = alice.get_balance_msat().await?;
    anyhow::ensure!(
        alice_after == alice_mid,
        "cancelled invoice moved a balance: {alice_mid} -> {alice_after}"
    );
    info!("  alice's balance unchanged at {alice_after} msat");

    Ok(())
}

async fn wait_for<F, Fut>(timeout: Duration, what: &str, mut check: F) -> Result<()>
where
    F: FnMut() -> Fut,
    Fut: std::future::Future<Output = Result<bool>>,
{
    let deadline = Instant::now() + timeout;
    loop {
        if check().await? {
            return Ok(());
        }
        anyhow::ensure!(Instant::now() < deadline, "timed out waiting for {what}");
        tokio::time::sleep(Duration::from_secs(2)).await;
    }
}
